        for r in rest+front_row_context:
            span=(sum(r['box_px'][0]>=g for g in gutters),sum(r['box_px'][2]>g for g in gutters))
            if r['_scan_id'] in rest_ids:span=block_rows.get(r['_scan_id'],span)
            column_runs[span].append(r)
        for column in column_runs.values():
            for row in scan_rows(column):
                group=[r for r in row if r['_scan_id'] in rest_ids]
                if group:items.append(dict(kind='line',runs=group,box_px=hull(r['box_px'] for r in group)))
        ordered=scan_order(items,gutters)
        # A display title and byline precede an independent side abstract.
